def _create_caching_extension(
    *,
    mode: SessionMode,
    auto_instantiate: bool,
    config_manager: MarimoConfigManager,
) -> CachingExtension:
    """Create the caching extension for a session.

    In EDIT mode the cache is read-write: it is enabled whenever cells are
    not auto-instantiated. In RUN mode the cache is read-only and is only
    enabled when `serve_cached_sessions_in_apps` is set in the runtime
    config.
    """
    if mode == SessionMode.EDIT:
        return CachingExtension(
            enabled=not auto_instantiate,
            mode=CacheMode.READ_WRITE,
        )

    runtime_config = config_manager.get_config().get("runtime", {})
    serve_cached = bool(
        runtime_config.get("serve_cached_sessions_in_apps", False)
    )
    return CachingExtension(
        enabled=serve_cached,
        mode=CacheMode.READ,
    )


